WITH test_c AS (
  SELECT id FROM customers WHERE is_test = true
),
test_t AS (
  SELECT id FROM tickets WHERE customer_id IN (SELECT id FROM test_c)
),
del_replies AS (
  DELETE FROM replies WHERE ticket_id IN (SELECT id FROM test_t) RETURNING 1
),
del_tickets AS (
  DELETE FROM tickets WHERE id IN (SELECT id FROM test_t) RETURNING 1
),
del_keys AS (
  DELETE FROM api_keys WHERE customer_id IN (SELECT id FROM test_c) RETURNING 1
),
del_customers AS (
  DELETE FROM customers WHERE id IN (SELECT id FROM test_c) RETURNING 1
)
SELECT
  (SELECT count(*) FROM del_replies) AS replies_deleted,
  (SELECT count(*) FROM del_tickets) AS tickets_deleted,
  (SELECT count(*) FROM del_keys) AS api_keys_deleted,
  (SELECT count(*) FROM del_customers) AS customers_deleted;

BEGIN;
DELETE FROM replies WHERE ticket_id IN (SELECT id FROM tickets WHERE customer_id IN (SELECT id FROM customers WHERE is_test = true));
DELETE FROM tickets WHERE customer_id IN (SELECT id FROM customers WHERE is_test = true);
DELETE FROM api_keys WHERE customer_id IN (SELECT id FROM customers WHERE is_test = true);
DELETE FROM customers WHERE is_test = true;
COMMIT;

begin;
with tc as (select id from customers where is_test = true),
tk as (select id from tickets where customer_id in (select id from tc))
, d_replies as (delete from replies where ticket_id in (select id from tk) returning 1)
, d_tickets as (delete from tickets where id in (select id from tk) returning 1)
, d_keys as (delete from api_keys where customer_id in (select id from tc) returning 1)
, d_customers as (delete from customers where id in (select id from tc) returning 1)
select (select count(*) from d_replies) as replies_deleted, (select count(*) from d_tickets) as tickets_deleted, (select count(*) from d_keys) as api_keys_deleted, (select count(*) from d_customers) as customers_deleted;
commit;

SELECT k.id, k.label, k.created_at, k.revoked_at, c.id AS customer_id, c.name
FROM public.api_keys k JOIN public.customers c ON c.id = k.customer_id
WHERE c.name ILIKE '%bramble%' ORDER BY k.id;

BEGIN;
CREATE TEMP TABLE _test_customers ON COMMIT DROP AS SELECT id FROM customers WHERE is_test;
CREATE TEMP TABLE _test_tickets ON COMMIT DROP AS SELECT id FROM tickets WHERE customer_id IN (SELECT id FROM _test_customers);
DELETE FROM replies WHERE ticket_id IN (SELECT id FROM _test_tickets);
DELETE FROM tickets WHERE id IN (SELECT id FROM _test_tickets);
DELETE FROM api_keys WHERE customer_id IN (SELECT id FROM _test_customers);
DELETE FROM customers WHERE id IN (SELECT id FROM _test_customers);
COMMIT;
SELECT (SELECT count(*) FROM customers WHERE is_test) AS test_customers_left,
  (SELECT count(*) FROM customers) AS customers_total,
  (SELECT count(*) FROM tickets) AS tickets_total,
  (SELECT count(*) FROM replies) AS replies_total,
  (SELECT count(*) FROM api_keys) AS api_keys_total;
